import { FormEvent, useState } from 'react';
import { JxButton, JxInputField, JxToastViewport, useJxToastQueue } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [error, setError] = useState<string | undefined>(undefined);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const value = email.trim();

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      setError('Укажите адрес вида name@example.com');
      return;
    }

    toasts.push({
      title: 'Готово',
      message: `Письмо с подтверждением отправлено на ${value}`,
      variant: 'success',
    });
    setEmail('');
    setError(undefined);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-gap, 12px)',
        maxWidth: 360,
      }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        autoComplete="email"
        placeholder="name@example.com"
        value={email}
        onChange={(event) => {
          setEmail(event.target.value);
          if (error) setError(undefined);
        }}
        errorText={error}
        helperText="Одно письмо в неделю, отписаться можно в любой момент."
      />

      <JxButton type="submit" variant="primary" disabled={email.trim().length === 0}>
        Подписаться
      </JxButton>

      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="top-right" />
    </form>
  );
}

